-- Store Expansion Phase 1A
-- Stable IDs are used because Prisma cuid values cannot be generated by SQL.

CREATE TABLE "store_types" (
  "id" TEXT NOT NULL,
  "slug" TEXT NOT NULL,
  "nameAr" TEXT NOT NULL,
  "icon" TEXT NOT NULL,
  "labels" JSONB NOT NULL,
  "freeProductLimit" INTEGER,
  "isActive" BOOLEAN NOT NULL DEFAULT true,
  "sortOrder" INTEGER NOT NULL DEFAULT 0,
  CONSTRAINT "store_types_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "store_types_slug_key" ON "store_types"("slug");
CREATE INDEX "store_types_isActive_sortOrder_idx" ON "store_types"("isActive", "sortOrder");

