ALTER TABLE "store_details" ADD COLUMN "storeTypeId" TEXT;
UPDATE "store_details" SET "storeTypeId" = 'st_general' WHERE "storeTypeId" IS NULL;

ALTER TABLE "store_details"
  ADD CONSTRAINT "store_details_storeTypeId_fkey"
  FOREIGN KEY ("storeTypeId") REFERENCES "store_types"("id")
  ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "store_details" ALTER COLUMN "storeTypeId" SET NOT NULL;
ALTER TABLE "store_details" ALTER COLUMN "storeTypeId" SET DEFAULT 'st_general';

CREATE INDEX "store_details_storeTypeId_idx" ON "store_details"("storeTypeId");

ALTER TABLE "product_categories" ADD COLUMN "storeTypeId" TEXT;

ALTER TABLE "product_categories"
  ADD CONSTRAINT "product_categories_storeTypeId_fkey"
  FOREIGN KEY ("storeTypeId") REFERENCES "store_types"("id")
  ON DELETE SET NULL ON UPDATE CASCADE;

CREATE INDEX "product_categories_storeTypeId_idx" ON "product_categories"("storeTypeId");

ALTER TYPE "AuditEventType" ADD VALUE 'ADMIN_STORE_TYPE_CHANGED';
